import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';

export type BookStatus = 'reading' | 'finished';

export interface Book {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: BookStatus;
  createdAt: string;
  finishedAt?: string;
}

export function getBooksFilePath(): string {
  return process.env.BOOKS_FILE_PATH || path.join(process.cwd(), 'data', 'books.json');
}

async function ensureBooksFile(filePath: string): Promise<void> {
  const dir = path.dirname(filePath);
  await fs.mkdir(dir, { recursive: true });
  try {
    await fs.access(filePath);
  } catch {
    await fs.writeFile(filePath, JSON.stringify([], null, 2), 'utf-8');
  }
}

export async function getBooks(): Promise<Book[]> {
  const filePath = getBooksFilePath();
  await ensureBooksFile(filePath);
  const raw = await fs.readFile(filePath, 'utf-8');
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export async function saveBooks(books: Book[]): Promise<void> {
  const filePath = getBooksFilePath();
  await ensureBooksFile(filePath);
  await fs.writeFile(filePath, JSON.stringify(books, null, 2), 'utf-8');
}

export async function getBookById(id: string): Promise<Book | undefined> {
  const books = await getBooks();
  return books.find((b) => b.id === id);
}

export interface AddBookInput {
  title: string;
  author: string;
  notes?: string;
  status?: BookStatus;
}

export async function addBook(input: AddBookInput): Promise<Book> {
  const title = input.title.trim();
  const author = input.author.trim();
  if (!title || !author) {
    throw new Error('Title and author are required');
  }

  const books = await getBooks();
  const status: BookStatus = input.status === 'finished' ? 'finished' : 'reading';
  const now = new Date().toISOString();

  const newBook: Book = {
    id: crypto.randomUUID(),
    title,
    author,
    notes: (input.notes ?? '').trim(),
    status,
    createdAt: now,
    ...(status === 'finished' ? { finishedAt: now } : {}),
  };

  books.unshift(newBook);
  await saveBooks(books);
  return newBook;
}

export interface UpdateBookInput {
  title?: string;
  author?: string;
  notes?: string;
  status?: BookStatus;
}

export async function updateBook(id: string, updates: UpdateBookInput): Promise<Book | undefined> {
  const books = await getBooks();
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) {
    return undefined;
  }

  const current = books[index];
  const nextStatus = updates.status ?? current.status;
  const now = new Date().toISOString();

  const updated: Book = {
    ...current,
    title: updates.title !== undefined ? updates.title.trim() || current.title : current.title,
    author: updates.author !== undefined ? updates.author.trim() || current.author : current.author,
    notes: updates.notes !== undefined ? updates.notes : current.notes,
    status: nextStatus,
    finishedAt:
      nextStatus === 'finished'
        ? current.finishedAt || now
        : undefined,
  };

  books[index] = updated;
  await saveBooks(books);
  return updated;
}

export async function deleteBook(id: string): Promise<boolean> {
  const books = await getBooks();
  const filtered = books.filter((b) => b.id !== id);
  if (filtered.length === books.length) {
    return false;
  }
  await saveBooks(filtered);
  return true;
}

import { NextResponse } from 'next/server';
import { addBook, getBooks } from '@/lib/books';

export const dynamic = 'force-dynamic';

export async function GET() {
  const books = await getBooks();
  return NextResponse.json(books);
}

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { title, author, notes, status } = body ?? {};

    if (!title || typeof title !== 'string' || !title.trim()) {
      return NextResponse.json({ error: 'Title is required' }, { status: 400 });
    }
    if (!author || typeof author !== 'string' || !author.trim()) {
      return NextResponse.json({ error: 'Author is required' }, { status: 400 });
    }

    const book = await addBook({
      title,
      author,
      notes: typeof notes === 'string' ? notes : '',
      status: status === 'finished' ? 'finished' : 'reading',
    });

    return NextResponse.json(book, { status: 201 });
  } catch (error) {
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Failed to add book' },
      { status: 400 }
    );
  }
}

import { NextResponse } from 'next/server';
import { deleteBook, getBookById, updateBook } from '@/lib/books';

export const dynamic = 'force-dynamic';

interface RouteContext {
  params: Promise<{ id: string }>;
}

export async function GET(_request: Request, context: RouteContext) {
  const { id } = await context.params;
  const book = await getBookById(id);
  if (!book) {
    return NextResponse.json({ error: 'Book not found' }, { status: 404 });
  }
  return NextResponse.json(book);
}

export async function PATCH(request: Request, context: RouteContext) {
  const { id } = await context.params;
  try {
    const body = await request.json();
    const updated = await updateBook(id, {
      title: typeof body?.title === 'string' ? body.title : undefined,
      author: typeof body?.author === 'string' ? body.author : undefined,
      notes: typeof body?.notes === 'string' ? body.notes : undefined,
      status:
        body?.status === 'finished' || body?.status === 'reading'
          ? body.status
          : undefined,
    });

    if (!updated) {
      return NextResponse.json({ error: 'Book not found' }, { status: 404 });
    }
    return NextResponse.json(updated);
  } catch (error) {
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Failed to update book' },
      { status: 400 }
    );
  }
}

export async function PUT(request: Request, context: RouteContext) {
  return PATCH(request, context);
}

export async function DELETE(_request: Request, context: RouteContext) {
  const { id } = await context.params;
  const removed = await deleteBook(id);
  if (!removed) {
    return NextResponse.json({ error: 'Book not found' }, { status: 404 });
  }
  return NextResponse.json({ ok: true });
}

