'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import type { Book } from '@/lib/books';

interface BookDashboardProps {
  initialBooks: Book[];
}

export default function BookDashboard({ initialBooks }: BookDashboardProps) {
  const router = useRouter();
  const [books, setBooks] = useState<Book[]>(initialBooks);
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [notes, setNotes] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [updatingId, setUpdatingId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const currentlyReading = books.filter((b) => b.status === 'reading');
  const finishedBooks = books.filter((b) => b.status === 'finished');

  async function handleAddBook(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(null);

    if (!title.trim() || !author.trim()) {
      setError('Please enter both a title and an author.');
      return;
    }

    setSubmitting(true);
    try {
      const res = await fetch('/api/books', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: title.trim(),
          author: author.trim(),
          notes: notes.trim(),
          status: 'reading',
        }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || 'Failed to add book');
      }

      const created: Book = await res.json();
      setBooks((prev) => [created, ...prev]);
      setTitle('');
      setAuthor('');
      setNotes('');
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong');
    } finally {
      setSubmitting(false);
    }
  }

  async function handleMarkFinished(bookId: string) {
    setUpdatingId(bookId);
    setError(null);
    try {
      const res = await fetch(`/api/books/${encodeURIComponent(bookId)}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'finished' }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || 'Failed to update book');
      }

      const updated: Book = await res.json();
      setBooks((prev) => prev.map((b) => (b.id === bookId ? updated : b)));
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to mark book as finished');
    } finally {
      setUpdatingId(null);
    }
  }

  return (
    <div>
      <section className="card" aria-labelledby="add-book-heading">
        <div className="section-header">
          <h2 id="add-book-heading" className="section-title">
            Add a Book
          </h2>
        </div>
        <form onSubmit={handleAddBook} className="form-grid">
          <div className="form-group">
            <label htmlFor="book-title" className="label">
              Title
            </label>
            <input
              id="book-title"
              name="title"
              type="text"
              className="input"
              placeholder="e.g. The Left Hand of Darkness"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="book-author" className="label">
              Author
            </label>
            <input
              id="book-author"
              name="author"
              type="text"
              className="input"
              placeholder="e.g. Ursula K. Le Guin"
              value={author}
              onChange={(e) => setAuthor(e.target.value)}
              required
            />
          </div>

          <div className="form-group full-width">
            <label htmlFor="book-notes" className="label">
              Notes
            </label>
            <textarea
              id="book-notes"
              name="notes"
              className="textarea"
              placeholder="Initial thoughts, favorite quotes, or why you picked it up..."
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
            />
          </div>

          <div className="form-group full-width">
            <div>
              <button type="submit" className="btn btn-primary" disabled={submitting}>
                {submitting ? 'Adding...' : 'Add Book'}
              </button>
            </div>
            {error && <p className="error-text" role="alert">{error}</p>}
          </div>
        </form>
      </section>

      <section className="section" aria-labelledby="currently-reading-heading">
        <div className="section-header">
          <h2 id="currently-reading-heading" className="section-title">
            Currently Reading
          </h2>
          <span className="count-pill">{currentlyReading.length}</span>
        </div>

        {currentlyReading.length === 0 ? (
          <p className="empty-state">No books currently being read. Add one above to get started.</p>
        ) : (
          <ul className="book-list">
            {currentlyReading.map((book) => (
              <li key={book.id} className="book-item">
                <div className="book-main">
                  <Link href={`/books/${book.id}`} className="book-link">
                    <h3 className="book-title">{book.title}</h3>
                  </Link>
                  <p className="book-author">by {book.author}</p>
                  {book.notes && <p className="book-notes-preview">{book.notes}</p>}
                </div>
                <div className="book-actions">
                  <button
                    type="button"
                    className="btn btn-secondary"
                    onClick={() => handleMarkFinished(book.id)}
                    disabled={updatingId === book.id}
                  >
                    {updatingId === book.id ? 'Saving...' : 'Mark as finished'}
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section className="section" aria-labelledby="finished-heading">
        <div className="section-header">
          <h2 id="finished-heading" className="section-title">
            Finished
          </h2>
          <span className="count-pill">{finishedBooks.length}</span>
        </div>

        {finishedBooks.length === 0 ? (
          <p className="empty-state">No finished books yet.</p>
        ) : (
          <ul className="book-list">
            {finishedBooks.map((book) => (
              <li key={book.id} className="book-item">
                <div className="book-main">
                  <Link href={`/books/${book.id}`} className="book-link">
                    <h3 className="book-title">{book.title}</h3>
                  </Link>
                  <p className="book-author">by {book.author}</p>
                  {book.notes && <p className="book-notes-preview">{book.notes}</p>}
                </div>
                <div className="book-actions">
                  <span className="badge badge-finished">Finished</span>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

