'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import type { Book } from '@/lib/books';

interface BookDetailClientProps {
  initialBook: Book;
}

export default function BookDetailClient({ initialBook }: BookDetailClientProps) {
  const router = useRouter();
  const [book, setBook] = useState<Book>(initialBook);
  const [notes, setNotes] = useState(initialBook.notes);
  const [editingNotes, setEditingNotes] = useState(false);
  const [saving, setSaving] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleToggleStatus() {
    const nextStatus = book.status === 'reading' ? 'finished' : 'reading';
    setSaving(true);
    setError(null);
    try {
      const res = await fetch(`/api/books/${encodeURIComponent(book.id)}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: nextStatus }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || 'Failed to update status');
      }

      const updated: Book = await res.json();
      setBook(updated);
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update status');
    } finally {
      setSaving(false);
    }
  }

  async function handleSaveNotes(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setSaving(true);
    setError(null);
    try {
      const res = await fetch(`/api/books/${encodeURIComponent(book.id)}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ notes }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || 'Failed to save notes');
      }

      const updated: Book = await res.json();
      setBook(updated);
      setNotes(updated.notes);
      setEditingNotes(false);
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save notes');
    } finally {
      setSaving(false);
    }
  }

  async function handleCopyLink() {
    try {
      const url = window.location.href;
      await navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Fallback if clipboard API fails
    }
  }

  return (
    <div>
      <div style={{ marginBottom: '1.25rem' }}>
        <Link href="/" className="btn btn-secondary">
          &larr; Back to all books
        </Link>
      </div>

      <article className="card">
        <div
          style={{
            display: 'flex',
            alignItems: 'flex-start',
            justifyContent: 'space-between',
            gap: '1rem',
            flexWrap: 'wrap',
            borderBottom: '1px solid var(--border)',
            paddingBottom: '1rem',
            marginBottom: '1.25rem',
          }}
        >
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', flexWrap: 'wrap' }}>
              <h2 style={{ fontSize: '1.5rem', fontWeight: 700, margin: 0 }}>{book.title}</h2>
              <span
                className={`badge ${
                  book.status === 'finished' ? 'badge-finished' : 'badge-reading'
                }`}
              >
                {book.status === 'finished' ? 'Finished' : 'Currently Reading'}
              </span>
            </div>
            <p style={{ fontSize: '1.05rem', color: 'var(--muted)', margin: '0.35rem 0 0' }}>
              by {book.author}
            </p>
          </div>

          <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
            {book.status === 'reading' ? (
              <button
                type="button"
                className="btn btn-primary"
                onClick={handleToggleStatus}
                disabled={saving}
              >
                Mark as finished
              </button>
            ) : (
              <button
                type="button"
                className="btn btn-secondary"
                onClick={handleToggleStatus}
                disabled={saving}
              >
                Move to currently reading
              </button>
            )}
            <button type="button" className="btn btn-secondary" onClick={handleCopyLink}>
              {copied ? 'Link copied!' : 'Copy link'}
            </button>
          </div>
        </div>

        <section aria-labelledby="notes-heading">
          <div className="section-header">
            <h3 id="notes-heading" className="section-title">
              Notes
            </h3>
            {!editingNotes && (
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => setEditingNotes(true)}
              >
                Edit notes
              </button>
            )}
          </div>

          {editingNotes ? (
            <form onSubmit={handleSaveNotes} style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
              <textarea
                aria-label="Notes"
                className="textarea"
                rows={5}
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Write your notes about this book..."
              />
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <button type="submit" className="btn btn-primary" disabled={saving}>
                  {saving ? 'Saving...' : 'Save notes'}
                </button>
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => {
                    setNotes(book.notes);
                    setEditingNotes(false);
                  }}
                  disabled={saving}
                >
                  Cancel
                </button>
              </div>
            </form>
          ) : book.notes ? (
            <div
              style={{
                whiteSpace: 'pre-wrap',
                background: 'var(--bg)',
                padding: '1rem',
                borderRadius: '6px',
                border: '1px solid var(--border)',
              }}
            >
              {book.notes}
            </div>
          ) : (
            <p className="empty-state">No notes added for this book yet.</p>
          )}
        </section>

        {error && (
          <p className="error-text" role="alert">
            {error}
          </p>
        )}
      </article>
    </div>
  );
}

import { notFound } from 'next/navigation';
import { getBookById } from '@/lib/books';
import BookDetailClient from '@/components/BookDetailClient';

export const dynamic = 'force-dynamic';

interface BookPageProps {
  params: Promise<{ id: string }>;
}

export default async function BookPage({ params }: BookPageProps) {
  const { id } = await params;
  const book = await getBookById(id);

  if (!book) {
    notFound();
  }

  return <BookDetailClient initialBook={book} />;
}

import Link from 'next/link';

export default function BookNotFound() {
  return (
    <div className="card" style={{ textAlign: 'center', padding: '2.5rem 1.5rem' }}>
      <h2 style={{ margin: '0 0 0.5rem' }}>Book not found</h2>
      <p style={{ color: 'var(--muted)', marginBottom: '1.25rem' }}>
        We couldn&apos;t find the book you were looking for.
      </p>
      <Link href="/" className="btn btn-primary">
        Back to reading list
      </Link>
    </div>
  );
}

