import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { addBook, getBookById, getBooks, updateBook, deleteBook } from '@/lib/books';
import { GET as getBooksRoute, POST as postBookRoute } from '@/app/api/books/route';
import { GET as getBookRoute, PATCH as patchBookRoute } from '@/app/api/books/[id]/route';

describe('books storage & API routes', () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'books-test-'));
    process.env.BOOKS_FILE_PATH = path.join(tempDir, 'books.json');
  });

  afterEach(async () => {
    delete process.env.BOOKS_FILE_PATH;
    await fs.rm(tempDir, { recursive: true, force: true });
  });

  it('starts empty and persists added books to JSON file', async () => {
    const initial = await getBooks();
    expect(initial).toEqual([]);

    const created = await addBook({
      title: 'Project Hail Mary',
      author: 'Andy Weir',
      notes: 'Great sci-fi read',
    });

    expect(created.id).toBeTruthy();
    expect(created.title).toBe('Project Hail Mary');
    expect(created.author).toBe('Andy Weir');
    expect(created.notes).toBe('Great sci-fi read');
    expect(created.status).toBe('reading');

    const rawFile = await fs.readFile(process.env.BOOKS_FILE_PATH!, 'utf-8');
    const saved = JSON.parse(rawFile);
    expect(saved).toHaveLength(1);
    expect(saved[0].title).toBe('Project Hail Mary');
  });

  it('marks a book as finished and retrieves it by id', async () => {
    const book = await addBook({
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'Arrakis',
    });

    const updated = await updateBook(book.id, { status: 'finished' });
    expect(updated?.status).toBe('finished');
    expect(updated?.finishedAt).toBeTruthy();

    const fetched = await getBookById(book.id);
    expect(fetched?.status).toBe('finished');
    expect(fetched?.title).toBe('Dune');
  });

  it('supports API route handlers for listing, creating, getting, and finishing a book', async () => {
    const createReq = new Request('http://localhost/api/books', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: 'Piranesi',
        author: 'Susanna Clarke',
        notes: 'The House is infinite.',
      }),
    });

    const createRes = await postBookRoute(createReq);
    expect(createRes.status).toBe(201);
    const createdBook = await createRes.json();
    expect(createdBook.title).toBe('Piranesi');
    expect(createdBook.status).toBe('reading');

    const listRes = await getBooksRoute();
    const listData = await listRes.json();
    expect(listData).toHaveLength(1);

    const singleRes = await getBookRoute(new Request(`http://localhost/api/books/${createdBook.id}`), {
      params: Promise.resolve({ id: createdBook.id }),
    });
    expect(singleRes.status).toBe(200);
    const singleBook = await singleRes.json();
    expect(singleBook.author).toBe('Susanna Clarke');
    expect(singleBook.notes).toBe('The House is infinite.');

    const patchReq = new Request(`http://localhost/api/books/${createdBook.id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: 'finished' }),
    });
    const patchRes = await patchBookRoute(patchReq, {
      params: Promise.resolve({ id: createdBook.id }),
    });
    expect(patchRes.status).toBe(200);
    const patchedBook = await patchRes.json();
    expect(patchedBook.status).toBe('finished');

    const removed = await deleteBook(createdBook.id);
    expect(removed).toBe(true);
  });
});

